/**
 * YAML fence body → base props, resolved steps, and validation issues.
 *
 * Two step forms, both resolved here so views never see either:
 *
 *   steps:  shallow patches, each over the *previous* step. Authors write
 *           deltas, which is what makes a walkthrough 25 lines instead of 250.
 *   frames: complete prop sets, each over the base. For bodies generated by
 *           a script, where a delta is more work than a snapshot.
 */

import yaml from "js-yaml";
import type { FenceSpec } from "./registry";
import {
  applyDefaults,
  isReservedStepKey,
  isReservedTopLevel,
  validateAttributes,
  type ValidationIssue,
} from "./schema";

export interface StepMeta {
  /** Prose for the AnnotationBar. */
  note?: string;
  /** 1-based line in `code` to highlight. */
  line?: number;
  /** 1-based line about to run. */
  next?: number;
  label?: string;
  breakpoint?: boolean;
  duration?: number;
  /** Key → explanation, surfaced when the reader selects that key. */
  why?: Record<string, string>;
  /** Pause until the reader selects this key (constructing exercises). */
  expect?: Record<string, unknown>;
}

export interface ParsedFence {
  /** Props with no steps applied. */
  base: Record<string, unknown>;
  /** Fully resolved props per step. Empty when the fence is static. */
  steps: Record<string, unknown>[];
  stepMeta: StepMeta[];
  code?: string;
  lang?: string;
  /** Explanations that apply to every step. */
  why?: Record<string, string>;
  /** Cross-widget correspondence, see `widgets/inspect.ts`. */
  link?: unknown;
  caption?: string;
  title?: string;
  issues: ValidationIssue[];
  /** Set when the body is not a YAML mapping at all. */
  error?: string;
}

/** Locate `key:` in the body so a validation issue can name a line. */
export function keyLine(source: string, key: string): number | undefined {
  const lines = source.split("\n");
  const re = new RegExp(`^\\s*-?\\s*["']?${key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}["']?\\s*:`);
  for (let i = 0; i < lines.length; i++) if (re.test(lines[i]!)) return i + 1;
  return undefined;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  return value as Record<string, unknown>;
}

function asInt(value: unknown): number | undefined {
  const n = Number(value);
  return Number.isFinite(n) ? n : undefined;
}

function whyMap(value: unknown): Record<string, string> | undefined {
  const rec = asRecord(value);
  if (!rec) return undefined;
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(rec)) out[k] = String(v);
  return out;
}

function stepMetaOf(patch: Record<string, unknown>): StepMeta {
  const meta: StepMeta = {};
  if (patch.note != null) meta.note = String(patch.note);
  if (patch.label != null) meta.label = String(patch.label);
  if (patch.line != null) meta.line = asInt(patch.line);
  if (patch.next != null) meta.next = asInt(patch.next);
  if (patch.breakpoint != null) meta.breakpoint = Boolean(patch.breakpoint);
  if (patch.duration != null) meta.duration = asInt(patch.duration);
  const why = whyMap(patch.why);
  if (why) meta.why = why;
  const expect = asRecord(patch.expect);
  if (expect) meta.expect = expect;
  return meta;
}

/** Drop reserved keys, leaving only what the view should receive. */
function propsOf(body: Record<string, unknown>, reserved: (k: string) => boolean): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(body)) if (!reserved(k)) out[k] = v;
  // `props:` is the escape hatch for a widget prop whose name collides with a
  // reserved key — `props: {title: "…"}` reaches the view, `title:` does not.
  const escaped = asRecord(body.props);
  if (escaped) Object.assign(out, escaped);
  return out;
}

export function parseFence(spec: FenceSpec, source: string): ParsedFence {
  const empty: ParsedFence = { base: {}, steps: [], stepMeta: [], issues: [] };

  let loaded: unknown;
  try {
    loaded = yaml.load(source);
  } catch (err) {
    return { ...empty, error: err instanceof Error ? err.message : String(err) };
  }
  const body = asRecord(loaded);
  if (!body) {
    return { ...empty, error: "expected a YAML mapping of widget properties" };
  }

  const reclaimed = new Set(spec.reclaims ?? []);
  const reservedTop = (key: string) => isReservedTopLevel(key) && !reclaimed.has(key);
  const reservedStep = (key: string) => isReservedStepKey(key) && !reclaimed.has(key);

  const lineOf = (key: string) => keyLine(source, key);
  const base = applyDefaults(spec.schema, propsOf(body, reservedTop));
  // Required keys are checked on the first *rendered* props, not the base: a
  // stepped fence may legitimately introduce `value:` only in step one.
  const issues: ValidationIssue[] = spec.legacy
    ? []
    : validateAttributes(spec.schema, base, { lineOf, mode: "base", requireAll: false });

  const rawSteps = Array.isArray(body.steps) ? body.steps : null;
  const rawFrames = reclaimed.has("frames") || !Array.isArray(body.frames) ? null : body.frames;
  const steps: Record<string, unknown>[] = [];
  const stepMeta: StepMeta[] = [];

  const list = rawSteps ?? rawFrames ?? [];
  const isPatch = rawSteps != null;
  let previous = base;

  list.forEach((raw, i) => {
    // A bare string step is a note over unchanged props — the shortest form
    // that still says something, and how most walkthroughs start.
    const patch = typeof raw === "string" ? { note: raw } : (asRecord(raw) ?? {});
    const patchProps = applyDefaults(spec.schema, propsOf(patch, reservedStep));
    if (!spec.legacy) {
      issues.push(
        ...validateAttributes(spec.schema, patchProps, {
          prefix: `steps[${i}]`,
          mode: "step",
          lineOf,
        }),
      );
    }
    const resolved = isPatch ? { ...previous, ...patchProps } : { ...base, ...patchProps };
    steps.push(resolved);
    stepMeta.push(stepMetaOf(patch));
    previous = resolved;
  });

  // Whatever the first frame actually shows is where "required" has to hold.
  if (!spec.legacy) {
    const first = steps[0] ?? base;
    for (const [key, attr] of Object.entries(spec.schema.attributes)) {
      if (attr.required && !(key in first)) {
        issues.push({
          path: key,
          message: `missing required key "${key}"`,
          line: lineOf(key),
          severity: "error",
        });
      }
    }
  }

  if (rawSteps && rawFrames) {
    issues.push({
      path: "frames",
      message: "a fence uses either steps or frames, not both; frames ignored",
      line: lineOf("frames"),
      severity: "warning",
    });
  }

  return {
    base,
    steps,
    stepMeta,
    code: body.code == null ? undefined : String(body.code),
    lang: body.lang == null ? undefined : String(body.lang),
    why: whyMap(body.why),
    link: body.link,
    caption: body.caption == null ? undefined : String(body.caption),
    title: body.title == null ? undefined : String(body.title),
    issues,
  };
}

/**
 * Is this body really ours?
 *
 * A bare language tag (` ```tree `) has to coexist with vaults that already
 * use it for directory listings, so it only claims the block when the YAML
 * parses to a mapping carrying one of the spec's required keys. The explicit
 * `kiwi-…` / `widget:…` spellings always claim it, and report their errors
 * loudly, for authors who would rather see a message than a code block.
 */
export function sniffFence(spec: FenceSpec, lang: string, source: string): boolean {
  if (lang !== spec.lang) return true;
  let loaded: unknown;
  try {
    loaded = yaml.load(source);
  } catch {
    return false;
  }
  const body = asRecord(loaded);
  if (!body) return false;
  if (spec.sniff) return spec.sniff(body);
  const required = spec.required ?? Object.entries(spec.schema.attributes)
    .filter(([, a]) => a.required)
    .map(([k]) => k);
  if (required.length === 0) return true;
  return required.some((key) => key in body);
}
